package authz

import (
	"time"

	"github.com/luwa07832/rbac-admin-api/internal/store"
)

// Service runs the time-aware authorization model over one store.
type Service struct {
	store *store.Store
}

// NewService wraps a store.
func NewService(st *store.Store) *Service { return &Service{store: st} }

// timings carries the canonical UTC texts of one write event.
type timings struct {
	occurredAt    string
	effectiveFrom string
}

// bindingRow is a flattened subject/role interval version.
type bindingRow struct {
	seq           int64
	roleID        string
	event         string
	occurredAt    string
	effectiveFrom string
	effectiveTo   string
	id            int64
}

// rolePermRow is a flattened role/permission interval version.
type rolePermRow struct {
	seq           int64
	roleID        string
	permissionID  string
	event         string
	occurredAt    string
	effectiveFrom string
	effectiveTo   string
	id            int64
}

// scopeRow is a flattened scoped authorization interval version. Exactly one
// of roleID and permissionID is set.
type scopeRow struct {
	seq           int64
	roleID        string
	permissionID  string
	scope         scopeRef
	event         string
	occurredAt    string
	effectiveFrom string
	effectiveTo   string
	id            int64
}

// snapshot is the complete read model needed for one decision or history
// query. Interval semantics are evaluated in Go in one place.
type snapshot struct {
	bindings []bindingRow
	rolePerm []rolePermRow
	scopes   []scopeRow

	// roleModel holds the current inheritance graph and the static operation
	// coverage of permissions; neither carries history intervals.
	roleModel
}

// roleModel is the history-free read model shared by every query: the
// current role inheritance graph in stored order and the operations
// statically covered by each permission.
type roleModel struct {
	roleParents    map[string][]string
	permOperations map[string]map[string]bool
}

func (s *Service) loadSnapshot(subject string) (*snapshot, error) {
	snap := &snapshot{roleModel: roleModel{
		roleParents:    map[string][]string{},
		permOperations: map[string]map[string]bool{},
	}}

	bindings, scopes, err := s.loadSubjectRows(subject)
	if err != nil {
		return nil, err
	}
	snap.bindings = bindings
	snap.scopes = scopes

	rolePermRows, err := s.loadRolePermissionRows()
	if err != nil {
		return nil, err
	}
	snap.rolePerm = rolePermRows

	model, err := s.loadRoleModel()
	if err != nil {
		return nil, err
	}
	snap.roleModel = model
	return snap, nil
}

// loadSubjectRows reads one subject's binding and scoped authorization
// interval versions. Scope rows that no longer parse are dropped, matching
// the read model everywhere else.
func (s *Service) loadSubjectRows(subject string) ([]bindingRow, []scopeRow, error) {
	bindingVersions, err := s.store.ListBindingVersions(subject)
	if err != nil {
		return nil, nil, err
	}
	bindings := make([]bindingRow, 0, len(bindingVersions))
	for _, version := range bindingVersions {
		bindings = append(bindings, bindingRow{
			seq:           version.Seq,
			roleID:        version.RoleID,
			event:         version.Event,
			occurredAt:    version.OccurredAt,
			effectiveFrom: version.EffectiveFrom,
			effectiveTo:   version.EffectiveTo,
			id:            version.ID,
		})
	}

	scopeVersions, err := s.store.ListScopeVersions(subject)
	if err != nil {
		return nil, nil, err
	}
	scopes := []scopeRow{}
	for _, version := range scopeVersions {
		parsedScope, ok := parseScope(version.ScopeText)
		if !ok {
			continue
		}
		scopes = append(scopes, scopeRow{
			seq:           version.Seq,
			roleID:        version.RoleID,
			permissionID:  version.PermissionID,
			scope:         parsedScope,
			event:         version.Event,
			occurredAt:    version.OccurredAt,
			effectiveFrom: version.EffectiveFrom,
			effectiveTo:   version.EffectiveTo,
			id:            version.ID,
		})
	}
	return bindings, scopes, nil
}

// loadRoleModel reads the current inheritance graph and static permission
// operation coverage. Both are present-time definitions without intervals.
func (s *Service) loadRoleModel() (roleModel, error) {
	model := roleModel{
		roleParents:    map[string][]string{},
		permOperations: map[string]map[string]bool{},
	}
	roleIDs, err := s.store.ListCatalog(store.CatalogRole)
	if err != nil {
		return roleModel{}, err
	}
	for _, roleID := range roleIDs {
		parents, err := s.store.RoleParents(roleID)
		if err != nil {
			return roleModel{}, err
		}
		model.roleParents[roleID] = parents
	}

	permissionIDs, err := s.store.ListCatalog(store.CatalogPermission)
	if err != nil {
		return roleModel{}, err
	}
	for _, permissionID := range permissionIDs {
		operations, err := s.store.PermissionOperations(permissionID)
		if err != nil {
			return roleModel{}, err
		}
		set := map[string]bool{}
		for _, operation := range operations {
			set[operation] = true
		}
		model.permOperations[permissionID] = set
	}
	return model, nil
}

// loadRolePermissionRows reads every role/permission grant interval version.
func (s *Service) loadRolePermissionRows() ([]rolePermRow, error) {
	rolePermVersions, err := s.store.ListRolePermissionVersions()
	if err != nil {
		return nil, err
	}
	rows := make([]rolePermRow, 0, len(rolePermVersions))
	for _, version := range rolePermVersions {
		rows = append(rows, rolePermRow{
			seq:           version.Seq,
			roleID:        version.RoleID,
			permissionID:  version.PermissionID,
			event:         version.Event,
			occurredAt:    version.OccurredAt,
			effectiveFrom: version.EffectiveFrom,
			effectiveTo:   version.EffectiveTo,
			id:            version.ID,
		})
	}
	return rows, nil
}

// resolveTimings resolves event and effective times. Both default to now;
// either may be supplied and effectiveFrom need not follow occurredAt.
func (s *Service) resolveTimings(occurredAtText, effectiveFromText string, effectiveField string) (timings, *Failure) {
	now := time.Now().UTC()
	result := timings{occurredAt: FormatTime(now), effectiveFrom: FormatTime(now)}
	if occurredAtText != "" {
		occurred, fail := ParseTime(occurredAtText)
		if fail != nil {
			fail.Field = "occurredAt"
			return timings{}, fail
		}
		result.occurredAt = FormatTime(occurred)
	}
	if effectiveFromText != "" {
		effective, fail := ParseTime(effectiveFromText)
		if fail != nil {
			fail.Field = effectiveField
			return timings{}, fail
		}
		result.effectiveFrom = FormatTime(effective)
	}
	return result, nil
}

// rowActive reports whether the half-open interval [from,to) contains t; an
// empty to marks an open interval.
func rowActive(from, to, at string) bool {
	if from > at {
		return false
	}
	return to == "" || to > at
}
package authz

import (
	"sort"
	"time"
)

// Denial reasons returned when granted is false.
const (
	ReasonNoRoleBinding       = "NO_ROLE_BINDING"
	ReasonNoPermissionBinding = "NO_PERMISSION_BINDING"
	ReasonOutOfScope          = "OUT_OF_SCOPE"
	ReasonNotEffective        = "NOT_EFFECTIVE"
)

// DecisionInput is the public authorize payload.
type DecisionInput struct {
	Subject     string `json:"subject"`
	Resource    string `json:"resource"`
	Operation   string `json:"operation"`
	EffectiveAt string `json:"effectiveAt,omitempty"`
}

// Match identifies the role-derived or direct authorization that explains a
// granted decision. Role is empty for direct permission grants.
type Match struct {
	Role       string
	Permission string
	Scope      string
}

// Decision is the service-level conclusion.
type Decision struct {
	Granted bool   `json:"-"`
	Reason  string `json:"-"`
	Match   *Match `json:"-"`
}

// Decide evaluates the triple at effectiveAt, defaulting to the current time.
func (s *Service) Decide(in DecisionInput) (*Decision, *Failure) {
	if fail := requireIdentifiers(in.Subject, in.Resource, in.Operation); fail != nil {
		return nil, fail
	}
	if fail := s.checkTriple(in.Subject, in.Resource, in.Operation); fail != nil {
		return nil, fail
	}
	at := time.Now().UTC()
	if in.EffectiveAt != "" {
		parsed, fail := ParseTime(in.EffectiveAt)
		if fail != nil {
			return nil, fail
		}
		at = parsed
	}

	snap, err := s.loadSnapshot(in.Subject)
	if err != nil {
		return nil, failure(TypeInvalidRequest, "", "could not evaluate authorization")
	}
	return evaluate(snap, in.Resource, in.Operation, at), nil
}

// candidate is one authorization path that structurally covers the triple.
type candidate struct {
	role       string
	permission string
	scope      scopeRef
	from       string
	to         string
}

func candidateLess(a, b candidate) bool {
	if cmp := compareScope(a.scope, b.scope); cmp != 0 {
		return cmp < 0
	}
	if a.permission != b.permission {
		return a.permission < b.permission
	}
	return a.role < b.role
}

// reachableRoles expands statically inherited roles from the entry set.
func reachableRoles(entries map[string]bool, parents map[string][]string) map[string]bool {
	reachable := map[string]bool{}
	queue := make([]string, 0, len(entries))
	for role := range entries {
		reachable[role] = true
		queue = append(queue, role)
	}
	for len(queue) > 0 {
		current := queue[0]
		queue = queue[1:]
		for _, parent := range parents[current] {
			if !reachable[parent] {
				reachable[parent] = true
				queue = append(queue, parent)
			}
		}
	}
	return reachable
}

func activeRoles(snap *snapshot, at string) map[string]bool {
	entries := map[string]bool{}
	for _, row := range snap.bindings {
		if rowActive(row.effectiveFrom, row.effectiveTo, at) {
			entries[row.roleID] = true
		}
	}
	return reachableRoles(entries, snap.roleParents)
}

func rolesEver(snap *snapshot) map[string]bool {
	entries := map[string]bool{}
	for _, row := range snap.bindings {
		entries[row.roleID] = true
	}
	return reachableRoles(entries, snap.roleParents)
}

func rolePermsActive(snap *snapshot, at string) map[[2]string]bool {
	result := map[[2]string]bool{}
	for _, row := range snap.rolePerm {
		if rowActive(row.effectiveFrom, row.effectiveTo, at) {
			result[[2]string{row.roleID, row.permissionID}] = true
		}
	}
	return result
}

func rolePermsEver(snap *snapshot) map[[2]string]bool {
	result := map[[2]string]bool{}
	for _, row := range snap.rolePerm {
		result[[2]string{row.roleID, row.permissionID}] = true
	}
	return result
}

func permissionCovers(snap *snapshot, permissionID, operation string) bool {
	return snap.permOperations[permissionID][operation]
}

// directCandidates returns scope rows that are direct permission grants,
// cover the operation and match the resource pattern. activeOnly filters by
// the given time.
func directCandidates(snap *snapshot, resource, operation, at string, activeOnly bool) []candidate {
	var result []candidate
	for _, row := range snap.scopes {
		if row.permissionID == "" {
			continue
		}
		if !permissionCovers(snap, row.permissionID, operation) || !row.scope.matches(resource) {
			continue
		}
		if activeOnly && !rowActive(row.effectiveFrom, row.effectiveTo, at) {
			continue
		}
		result = append(result, candidate{
			permission: row.permissionID,
			scope:      row.scope,
			from:       row.effectiveFrom,
			to:         row.effectiveTo,
		})
	}
	return result
}

// roleCandidates returns role-derived scope rows reachable through the given
// role set and covering role/permission pairs active at the layer time.
func roleCandidates(snap *snapshot, roles map[string]bool, rolePerms map[[2]string]bool,
	resource, operation, at string, activeOnly bool) []candidate {

	var result []candidate
	for _, row := range snap.scopes {
		if row.permissionID != "" || !roles[row.roleID] || !row.scope.matches(resource) {
			continue
		}
		for pair := range rolePerms {
			if pair[0] != row.roleID || !permissionCovers(snap, pair[1], operation) {
				continue
			}
			if activeOnly && !rowActive(row.effectiveFrom, row.effectiveTo, at) {
				continue
			}
			result = append(result, candidate{
				role:       row.roleID,
				permission: pair[1],
				scope:      row.scope,
				from:       row.effectiveFrom,
				to:         row.effectiveTo,
			})
		}
	}
	return result
}

// evaluate applies the published precedence:
//
//  1. a chain active now (binding, permission, scope interval all contain t)
//     with a scope pattern covering the resource grants;
//  2. otherwise the first layer that structurally existed at some point but is
//     not active now yields NOT_EFFECTIVE;
//  3. a layer that never existed yields its structural reason, with direct
//     permission grants bypassing the role layers.
func evaluate(snap *snapshot, resource, operation string, at time.Time) *Decision {
	atText := FormatTime(at)

	rolesNow := activeRoles(snap, atText)
	rolesPast := rolesEver(snap)
	rolePermsNow := rolePermsActive(snap, atText)
	rolePermsAll := rolePermsEver(snap)

	directNow := directCandidates(snap, resource, operation, atText, true)
	directEver := directCandidates(snap, resource, operation, atText, false)
	roleNowCandidates := roleCandidates(snap, rolesNow, rolePermsNow, resource, operation, atText, true)

	if len(directNow) > 0 {
		return best(directNow)
	}
	if len(roleNowCandidates) > 0 {
		return best(roleNowCandidates)
	}

	// Layer 1 (role-derived path only).
	if len(rolesNow) == 0 && len(rolesPast) > 0 {
		return denied(ReasonNotEffective)
	}

	// Layer 2. A role-derived permission covering the operation is a pair
	// active at the layer time; direct grants live entirely on this layer.
	roleCoversNow := hasCoveringPair(snap, rolesNow, rolePermsNow, operation)
	roleCoversEver := hasCoveringPair(snap, rolesPast, rolePermsAll, operation)

	if !roleCoversNow && (len(directEver) > 0 || roleCoversEver) {
		return denied(ReasonNotEffective)
	}

	// Layer 3. Consider scope rows for paths whose first two layers are
	// active now; an interval that exists but is not active now beats the
	// pattern-mismatch outcome.
	scopeRowsForActivePaths := roleCandidates(snap, rolesNow, rolePermsNow, resource, operation, atText, false)
	if len(directEver) > 0 {
		scopeRowsForActivePaths = append(scopeRowsForActivePaths, directEver...)
	}
	if len(scopeRowsForActivePaths) > 0 {
		return denied(ReasonNotEffective)
	}

	// Structural denials at the first missing layer.
	if len(rolesNow) == 0 {
		return denied(ReasonNoRoleBinding)
	}
	if !roleCoversNow {
		return denied(ReasonNoPermissionBinding)
	}
	return denied(ReasonOutOfScope)
}

func hasCoveringPair(snap *snapshot, roles map[string]bool, rolePerms map[[2]string]bool, operation string) bool {
	for pair := range rolePerms {
		if roles[pair[0]] && permissionCovers(snap, pair[1], operation) {
			return true
		}
	}
	return false
}

func best(candidates []candidate) *Decision {
	sort.SliceStable(candidates, func(i, j int) bool { return candidateLess(candidates[i], candidates[j]) })
	chosen := candidates[0]
	return &Decision{
		Granted: true,
		Match: &Match{
			Role:       chosen.role,
			Permission: chosen.permission,
			Scope:      chosen.scope.text,
		},
	}
}

func denied(reason string) *Decision {
	return &Decision{Granted: false, Reason: reason}
}

